INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (2, N'Fuller', N'Andrew', N'Vice President, Sales', N'Dr.', '02/19/1952', '08/14/1992', N'908 W. Capital Way', N'Tacoma', N'WA', N'98401', N'USA', N'(206) 555-9482', N'3457', 'Andrew received his BTS commercial in 1974 and a Ph.D. in international marketing from the University of Dallas in 1981.  He is fluent in French and Italian and reads German.  He joined the company as a sales representative, was promoted to sales manager in January 1992 and to vice president of sales in March 1993.  Andrew is a member of the Sales Management Roundtable, the Seattle Chamber of Commerce, and the Pacific Rim Importers Association.', null);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (1, N'Davolio', N'Nancy', N'Sales Representative', N'Ms.', '12/08/1948', '05/01/1992', N'507 - 20th Ave. E.Apt. 2A', N'Seattle', N'WA', N'98122', N'USA', N'(206) 555-9857', N'5467', 'Education includes a BA in psychology from Colorado State University in 1970.  She also completed "The Art of the Cold Call."  Nancy is a member of Toastmasters International.', 2);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (3, N'Leverling', N'Janet', N'Sales Representative', N'Ms.', '08/30/1963', '04/01/1992', N'722 Moss Bay Blvd.', N'Kirkland', N'WA', N'98033', N'USA', N'(206) 555-3412', N'3355', 'Janet has a BS degree in chemistry from Boston College (1984).  She has also completed a certificate program in food retailing management.  Janet was hired as a sales associate in 1991 and promoted to sales representative in February 1992.', 2);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (4, N'Peacock', N'Margaret', N'Sales Representative', N'Mrs.', '01/24/1970', '05/03/1993', N'4110 Old Redmond Rd.', N'Redmond', N'WA', N'98052', N'USA', N'(206) 555-8122', N'5176', 'Margaret holds a BA in English literature from Concordia College (1958) and an MA from the American Institute of Culinary Arts (1966).  She was assigned to the London office temporarily from July through November 1992.', 2);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (5, N'Buchanan', N'Steven', N'Sales Manager', N'Mr.', '03/04/1955', '10/17/1993', N'14 Garrett Hill', N'London', null, N'SW1 8JR', N'UK', N'(71) 555-4848', N'3453', 'Steven Buchanan graduated from St. Andrews University, Scotland, with a BSC degree in 1976.  Upon joining the company as a sales representative in 1992, he spent 6 months in an orientation program at the Seattle office and then returned to his permanent post in London.  He was promoted to sales manager in March 1993.  Mr. Buchanan has completed the courses "Successful Telemarketing" and "International Sales Management."  He is fluent in French.', 2);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (6, N'Suyama', N'Michael', N'Sales Representative', N'Mr.', '07/02/1963', '10/17/1993', N'Coventry House Miner Rd.', N'London', null, N'EC2 7JR', N'UK', N'(71) 555-7773', N'428', 'Michael is a graduate of Sussex University (MA, economics, 1983) and the University of California at Los Angeles (MBA, marketing, 1986).  He has also taken the courses "Multi-Cultural Selling" and "Time Management for the Sales Professional."  He is fluent in Japanese and can read and write French, Portuguese, and Spanish.', 5);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (7, N'King', N'Robert', N'Sales Representative', N'Mr.', '05/29/1960', '01/02/1994', N'Edgeham Hollow Winchester Way', N'London', null, N'RG1 9SP', N'UK', N'(71) 555-5598', N'465', 'Robert King served in the Peace Corps and traveled extensively before completing his degree in English at the University of Michigan in 1992, the year he joined the company.  After completing a course entitled "Selling in Europe," he was transferred to the London office in March 1993.', 5);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (8, N'Callahan', N'Laura', N'Inside Sales Coordinator', N'Ms.', '01/09/1958', '03/05/1994', N'4726 - 11th Ave. N.E.', N'Seattle', N'WA', N'98105', N'USA', N'(206) 555-1189', N'2344', 'Laura received a BA in psychology from the University of Washington.  She has also completed a course in business French.  She reads and writes French.', 2);
INSERT INTO NORTHWIND.EMPLOYEES(EMPLOYEEID, LASTNAME, FIRSTNAME, TITLE, TITLEOFCOURTESY, BIRTHDATE, HIREDATE, ADDRESS, CITY, REGION, POSTALCODE, COUNTRY, HOMEPHONE, EXTENSION, NOTES, REPORTSTO) VALUES (9, N'Dodsworth', N'Anne', N'Sales Representative', N'Ms.', '01/27/1966', '11/15/1994', N'7 Houndstooth Rd.', N'London', null, N'WG2 7LT', N'UK', N'(71) 555-4444', N'452', 'Anne has a BA degree in English from St. Lawrence College.  She is fluent in French and German.', 5);
